IF @definition<=@previous THROW 51000,'FIXTURE_RESTORATION_NOT_SELECTED',1;
DECLARE @fixture bigint=(SELECT fixture_pk FROM model.fixture WHERE semantic_object_definition_pk=@previous);
IF @fixture IS NULL THROW 51000,'FIXTURE_NORMALIZED_ROW_MISSING',1;
UPDATE model.fixture SET semantic_object_definition_pk=@definition,definition_digest=@digest,_owner_definition_pk=CASE WHEN _owner_definition_pk=@previous THEN @definition ELSE _owner_definition_pk END WHERE fixture_pk=@fixture;
DECLARE @input nvarchar(max)=JSON_QUERY(@semantics,'$.fixture.input'),@bytes varbinary(max),@input_digest binary(32);
SET @bytes=CONVERT(varbinary(max),CONVERT(varchar(max),@input COLLATE Latin1_General_100_BIN2_UTF8));SET @input_digest=HASHBYTES('SHA2_256',@bytes);
IF NOT EXISTS(SELECT 1 FROM source.content_object WHERE content_digest=@input_digest) INSERT source.content_object(content_digest,content_bytes,byte_length) VALUES(@input_digest,@bytes,DATALENGTH(@bytes));
UPDATE model.fixture_case SET input_content_pk=(SELECT content_object_pk FROM source.content_object WHERE content_digest=@input_digest) WHERE fixture_pk=@fixture;
UPDATE model.fixture_case SET _owner_definition_pk=@definition WHERE _owner_definition_pk=@previous;
UPDATE model.fixture_assertion SET _owner_definition_pk=@definition WHERE _owner_definition_pk=@previous;
UPDATE model.fixture_assertion_condition SET _owner_definition_pk=@definition WHERE _owner_definition_pk=@previous;
UPDATE model.fixture_port_outcome SET _owner_definition_pk=@definition WHERE _owner_definition_pk=@previous;
UPDATE model.fixture_scenario_step SET _owner_definition_pk=@definition WHERE _owner_definition_pk=@previous;
SELECT N'refuse-unadmitted-and-unconformed-providers' AS fixture_id,@definition AS definition_pk,JSON_VALUE(@semantics,'$.fixture.expected.disposition') AS expected_disposition,LOWER(CONVERT(varchar(64),@input_digest,2)) AS input_digest;
GO
COMMIT TRANSACTION;
